// VKU AI Student Support
// Chuẩn hóa câu hỏi sinh viên nhận từ Webhook

const items = $input.all();

return items.map((item) => {
  const rawQuestion = item.json.body?.question;

  const valid =
    typeof rawQuestion === 'string' &&
    rawQuestion.trim().length > 0;

  const question = valid
    ? rawQuestion.trim().replace(/\s+/g, ' ')
    : '';

  const normalizedQuestion = question.toLocaleLowerCase('vi');

  return {
    json: {
      question: question,
      normalized_question: normalizedQuestion,
      valid: valid,
      timestamp: new Date().toISOString()
    }
  };
});

// Lấy câu hỏi đã được chuẩn hóa từ node trước
const input = $('Code in JavaScript').first().json;

const question = input.question;
const normalizedQuestion = input.normalized_question;
const valid = input.valid;

// Lấy danh sách FAQ từ PostgreSQL
const faqs = $input.all().map(item => item.json);

// Chuẩn hóa văn bản để so sánh
function normalize(text) {
  return String(text || '')
    .toLocaleLowerCase('vi')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Kiểm tra câu hỏi hợp lệ
if (!valid) {
  return [{
    json: {
      success: false,
      question: question,
      answer: 'Vui lòng nhập câu hỏi hợp lệ.',
      matched: false
    }
  }];
}

const searchText = normalize(normalizedQuestion);

let bestMatch = null;
let bestScore = 0;

// Tìm FAQ phù hợp nhất
for (const faq of faqs) {
  let score = 0;

  const faqQuestion = normalize(faq.question);
  const keywords = Array.isArray(faq.keywords)
    ? faq.keywords
    : [];

  // Ưu tiên câu hỏi trùng khớp hoàn toàn
  if (searchText === faqQuestion) {
    score += 100;
  }

  // So sánh theo từ khóa
  for (const keyword of keywords) {
    const normalizedKeyword = normalize(keyword);

    if (
      normalizedKeyword &&
      searchText.includes(normalizedKeyword)
    ) {
      score += 10;
    }
  }

  if (score > bestScore) {
    bestScore = score;
    bestMatch = faq;
  }
}

// Trường hợp tìm thấy FAQ
if (bestMatch && bestScore > 0) {
  return [{
    json: {
      success: true,
      question: question,
      answer: bestMatch.answer,
      matched: true,
      faq_id: bestMatch.id,
      category: bestMatch.category,
      score: bestScore,
      verified: bestMatch.verified
    }
  }];
}

// Trường hợp không tìm thấy FAQ
return [{
  json: {
    success: true,
    question: question,
    answer: 'Hiện tại hệ thống chưa có thông tin phù hợp với câu hỏi của bạn. Vui lòng liên hệ bộ phận hỗ trợ sinh viên VKU để được hướng dẫn.',
    matched: false,
    faq_id: null,
    category: null,
    score: 0,
    verified: false
  }
}];
